struct sample{unsigned prefix,scenario,failure,calls,trace_count,mutate,nested,stop;bool rust;int status;struct fixture *fixture;size_t used;char trace[16384],result[16384],message[256];};static struct sample *active;
static int reference_interfaces(lua_State *L);static int lua_get_ifaddrs(lua_State *L);
static void log_bytes(const void *data,size_t length){const uint8_t *p=data;for(size_t i=0;i<length;++i){CHECK(active->used+2<sizeof(active->trace));int n=snprintf(active->trace+active->used,sizeof(active->trace)-active->used,"%02x",p[i]);CHECK(n==2);active->used+=2;}}
static void trace_rawset(lua_State *L,int index){
    ++active->trace_count;int type=lua_type(L,-2);if(type==LUA_TSTRING){size_t size;const char *key=lua_tolstring(L,-2,&size);log_bytes(key,size);}else{lua_Integer key=lua_tointeger(L,-2);log_bytes(&key,sizeof(key));}int value=lua_type(L,-1);log_bytes(&value,sizeof(value));if(value==LUA_TSTRING){size_t size;const char *text=lua_tolstring(L,-1,&size);log_bytes(text,size);}else if(value==LUA_TNUMBER){lua_Integer number=lua_tointeger(L,-1);log_bytes(&number,sizeof(number));}active->trace[active->used++]=';';active->trace[active->used]=0;
    char key[32]={0};if(type==LUA_TSTRING)snprintf(key,sizeof(key),"%s",lua_tostring(L,-2));lua_rawset(L,index);
    if(active->stop && active->trace_count==active->stop)luaL_error(L,"interface checkpoint");
    if(active->mutate && active->fixture && !strcmp(key,"guid")){IP_ADAPTER_ADDRESSES *a=&active->fixture->adapters[active->scenario&1?2:0];a->IfIndex=777;a->Mtu=1234;a->TransmitLinkSpeed=UINT64_MAX;a->Ipv4Metric=999;++mutations;}
    if(active->mutate && active->fixture && !strcmp(key,"netmask")){for(unsigned i=0;i<8;++i)if(active->fixture->sockets[i].ss_family==AF_INET)((struct sockaddr_in *)&active->fixture->sockets[i])->sin_addr.s_addr^=0x00000100u;++mutations;}
    if(active->mutate==2 && !active->nested && !strcmp(key,"guid")){struct fixture *outer=active->fixture;active->nested=1;int top=lua_gettop(L);CHECK((active->rust?lua_get_ifaddrs:reference_interfaces)(L)==1);CHECK(lua_gettop(L)==top+1);lua_pop(L,1);active->fixture=outer;++reentries;}
}
