struct allocator{bool armed;unsigned limit,calls,rejected,live;};static struct allocator *fault_allocator;
static void *allocate(void *context,void *pointer,size_t previous,size_t next){struct allocator *a=context;if(!next){if(pointer){CHECK(a->live);--a->live;}free(pointer);return NULL;}if(a->armed && next>previous && a->calls++>=a->limit){++a->rejected;return NULL;}bool fresh=!pointer;void *result=realloc(pointer,next);if(result && fresh)++a->live;return result;}
static const char *serialize="function SERIAL(v) if type(v)~='table' then return type(v)..':'..string.format('%q',tostring(v)) end local keys={} for k in pairs(v)do keys[#keys+1]=k end table.sort(keys,function(a,b)return tostring(a)<tostring(b)end) local out='{' for _,k in ipairs(keys)do out=out..SERIAL(k)..'='..SERIAL(v[k])..';' end return out..'}' end";
static lua_State *new_vm(struct allocator *a){lua_State *L=a?lua_newstate(allocate,a):luaL_newstate();CHECK(L);luaL_openlibs(L);luaJIT_setmode(L,0,LUAJIT_MODE_ENGINE|LUAJIT_MODE_OFF);CHECK(!luaL_dostring(L,serialize));return L;}
static void execute(lua_State *L,struct sample *s){active=s;lua_settop(L,0);lua_pushcfunction(L,s->rust?lua_get_ifaddrs:reference_interfaces);if(fault_allocator){fault_allocator->armed=true;fault_allocator->calls=fault_allocator->rejected=0;}s->status=lua_pcall(L,0,1,0);if(fault_allocator)fault_allocator->armed=false;CHECK(lua_gettop(L)==1);if(s->status){const char *msg=lua_tostring(L,-1);snprintf(s->message,sizeof(s->message),"%s",msg?msg:"");}else{lua_getglobal(L,"SERIAL");lua_pushvalue(L,1);CHECK(!lua_pcall(L,1,1,0));size_t n;const char *result=lua_tolstring(L,-1,&n);CHECK(n<sizeof(s->result));memcpy(s->result,result,n+1);}lua_settop(L,0);s->fixture=NULL;}
static void compare(lua_State *L,unsigned prefix,unsigned scenario,unsigned failure,unsigned mutation){struct sample a={.prefix=prefix,.scenario=scenario,.failure=failure,.mutate=mutation},b=a;b.rust=true;execute(L,&a);execute(L,&b);if(a.status!=b.status || a.calls!=b.calls || strcmp(a.trace,b.trace) || strcmp(a.result,b.result) || strcmp(a.message,b.message)){fprintf(stderr,"DETAIL prefix=%u scenario=%u failure=%u mutation=%u olderr=%d newerr=%d oldcalls=%u newcalls=%u\nold=%s\nnew=%s\noldtrace=%s\nnewtrace=%s\n",prefix,scenario,failure,mutation,a.status,b.status,a.calls,b.calls,a.result,b.result,a.trace,b.trace);CHECK(false);}++cases;}
struct guard{uint8_t *base,*end;};static struct guard guard_new(void){struct guard g;g.base=VirtualAlloc(NULL,8192,MEM_RESERVE|MEM_COMMIT,PAGE_READWRITE);CHECK(g.base);g.end=g.base+4096;DWORD old;CHECK(VirtualProtect(g.end,4096,PAGE_NOACCESS,&old));return g;}
static void boundaries_check(void){_Alignas(8)uint8_t memory[256]={0};zapret_lua_interface_cursor c;zapret_lua_interface_field f;CHECK(!zapret_lua_interfaces_begin(NULL,NULL));++boundaries;CHECK(!zapret_lua_interfaces_begin((void *)(memory+1),&c));++boundaries;CHECK(!zapret_lua_interfaces_begin(NULL,(void *)(memory+1)));++boundaries;CHECK(!zapret_lua_interfaces_next(NULL,&f));++boundaries;CHECK(!zapret_lua_interfaces_next(&c,NULL));++boundaries;CHECK(zapret_lua_interfaces_begin(NULL,&c));CHECK(zapret_lua_interfaces_next(&c,&f) && f.kind==0);CHECK(!zapret_lua_interfaces_next(&c,&f));++boundaries;
    for(unsigned bad=0;bad<4;++bad){CHECK(zapret_lua_interfaces_begin(NULL,&c));if(bad==0)c.phase=99;else if(bad==1){c.phase=1;}else if(bad==2){c.adapter=(void *)(memory+1);}else{c.phase=17;c.adapter=(void *)memory;c.address=(void *)(memory+1);}CHECK(!zapret_lua_interfaces_next(&c,&f));++boundaries;}
    struct guard a=guard_new(),b=guard_new(),s=guard_new();IP_ADAPTER_ADDRESSES *adapter=(void *)(a.end-sizeof(*adapter));IP_ADAPTER_UNICAST_ADDRESS_LH *address=(void *)(b.end-sizeof(*address));memset(adapter,0,sizeof(*adapter));memset(address,0,sizeof(*address));adapter->IfIndex=4294967295;adapter->OperStatus=IfOperStatusUp;adapter->FirstUnicastAddress=address;address->Address.lpSockaddr=(void *)(s.end-sizeof(struct sockaddr_in6));address->Address.lpSockaddr->sa_family=AF_INET6;address->OnLinkPrefixLength=128;memset((char *)address->Address.lpSockaddr+8,7,16);CHECK(zapret_lua_interfaces_begin(adapter,&c));DWORD old;CHECK(VirtualProtect(a.base,4096,PAGE_READONLY,&old));CHECK(VirtualProtect(b.base,4096,PAGE_READONLY,&old));CHECK(VirtualProtect(s.base,4096,PAGE_READONLY,&old));unsigned steps=0,addresses=0;do{CHECK(zapret_lua_interfaces_next(&c,&f));CHECK(++steps<64);if(f.kind==7 && !strcmp(f.name,"addr")){CHECK(f.length==16 && f.bytes[0]==7);++addresses;}}while(f.kind);CHECK(addresses==2);++boundaries;CHECK(VirtualFree(a.base,0,MEM_RELEASE) && VirtualFree(b.base,0,MEM_RELEASE) && VirtualFree(s.base,0,MEM_RELEASE));
}
static void faults(void){for(unsigned failure=0;failure<5;++failure){lua_State *baseline=new_vm(NULL);struct sample normal={.prefix=24,.scenario=0,.failure=failure};execute(baseline,&normal);CHECK(!normal.status);lua_close(baseline);for(unsigned side=0;side<2;++side)for(unsigned limit=0;limit<128;++limit){struct allocator a={.limit=limit};lua_State *L=new_vm(&a);struct sample s={.prefix=24,.scenario=0,.failure=failure,.rust=side!=0};fault_allocator=&a;execute(L,&s);fault_allocator=NULL;CHECK(s.used<=normal.used && !strncmp(normal.trace,s.trace,s.used));if(s.status){CHECK(s.status==LUA_ERRMEM && a.rejected);++vm_faults;}else CHECK(!a.rejected && !strcmp(s.result,normal.result) && !strcmp(s.trace,normal.trace) && s.calls==normal.calls);lua_close(L);CHECK(!a.live);++fault_cases;}}CHECK(vm_faults>20);}
int main(void){lua_State *L=new_vm(NULL);for(unsigned prefix=0;prefix<256;++prefix)for(unsigned scenario=0;scenario<64;++scenario)compare(L,prefix,scenario,0,0);for(unsigned prefix=0;prefix<=128;prefix+=8)for(unsigned failure=0;failure<5;++failure)for(unsigned mutation=0;mutation<3;++mutation)compare(L,prefix,0,failure,mutation);lua_close(L);boundaries_check();faults();printf("PASS lua_interfaces cases=%u boundaries=%u reentries=%u mutable_snapshots=%u fault_cases=%u vm_allocation_faults=%u real_luajit=1 exact_field_order=1 all_prefix_lengths=1 duplicate_addr_writes=1 windows_query_failures=1 guarded_readonly_views=1 c_only_unwind=1 vm_allocations_released=1\n",cases,boundaries,reentries,mutations,fault_cases,vm_faults);return 0;}
